package io.aetheris.orchestrator.stage9;
import jakarta.persistence.*;import java.time.Instant;import java.util.*;import java.util.stream.Collectors;
@Entity @Table(name="aetheris_stage9_worker_capabilities")
public class WorkerCapabilityEntity {@Id @Column(length=160) private String workerId;@Column(nullable=false,length=2000) private String capabilitiesCsv;@Column(nullable=false,length=1000) private String lanesCsv;private Instant lastAssignedAt;@Column(nullable=false) private Instant updatedAt;protected WorkerCapabilityEntity(){}public WorkerCapabilityEntity(String workerId,Set<String> capabilities,Set<String> lanes){this.workerId=workerId;update(capabilities,lanes);}public String getWorkerId(){return workerId;}public Set<String> getCapabilities(){return parse(capabilitiesCsv);}public Set<String> getLanes(){return parse(lanesCsv);}public Instant getLastAssignedAt(){return lastAssignedAt;}public Instant getUpdatedAt(){return updatedAt;}public void update(Set<String> c,Set<String> l){capabilitiesCsv=csv(c);lanesCsv=csv(l==null||l.isEmpty()?Set.of("*"):l);updatedAt=Instant.now();}public boolean supports(Set<String> required,String lane){return getCapabilities().containsAll(required)&&(getLanes().contains("*")||getLanes().contains(lane));}public void assigned(){lastAssignedAt=Instant.now();updatedAt=lastAssignedAt;}private String csv(Set<String>s){if(s==null)return"";return s.stream().filter(Objects::nonNull).map(String::trim).filter(x->!x.isBlank()).map(String::toLowerCase).distinct().sorted().collect(Collectors.joining(","));}private Set<String> parse(String s){if(s==null||s.isBlank())return Set.of();return Arrays.stream(s.split(",")).map(String::trim).filter(x->!x.isBlank()).collect(Collectors.toCollection(LinkedHashSet::new));}}
